{"path": "/tmp/sv-733aab2a433f4385a0651f2f6b1bab3c/Components/Chat/MessageInput.razor", "file_text": "@namespace sv_733aab2a433f4385a0651f2f6b1bab3c.Components.Chat

<div class="message-input">
    <textarea class="message-textarea"
              placeholder="@Placeholder"
              @bind="text"
              @onkeydown="HandleKeyDown"
              rows="2"></textarea>
    <button class="send-btn" @onclick="Send" disabled="@string.IsNullOrWhiteSpace(text)">
        @ButtonLabel
    </button>
</div>

@code {
    [Parameter] public string Placeholder { get; set; } = "Type a message…";
    [Parameter] public string ButtonLabel { get; set; } = "Send";
    [Parameter] public EventCallback<string> OnSend { get; set; }

    private string text = string.Empty;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await Send();
        }
    }

    private async Task Send()
    {
        if (string.IsNullOrWhiteSpace(text)) return;
        var content = text.Trim();
        text = string.Empty;
        await OnSend.InvokeAsync(content);
    }
}
"}

{"path": "/tmp/sv-733aab2a433f4385a0651f2f6b1bab3c/Components/Chat/MessageInput.razor.css", "file_text": ".message-input {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #e0e0e0;
    background: #fff;
    align-items: flex-end;
}

.message-textarea {
    flex: 1;
    resize: none;
    border: 1px solid #ccc;
    border-radius: 8px;
    padding: 8px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-textarea:focus {
    border-color: #4a90d9;
}

.send-btn {
    background-color: #4a90d9;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 8px 18px;
    font-weight: 600;
    cursor: pointer;
    white-space: nowrap;
    transition: background-color 0.15s;
}

.send-btn:hover:not(:disabled) {
    background-color: #357abd;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}
"}

