.thread-panel {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    background: #fff;
    border-left: 1px solid #e0e0e0;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
}

.thread-header h4 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    color: #666;
    padding: 4px 8px;
    border-radius: 4px;
    line-height: 1;
    transition: background-color 0.15s;
}

.close-btn:hover {
    background-color: #f0f0f0;
    color: #333;
}

.thread-root {
    padding: 12px 16px;
    background: #f7f7f8;
    border-bottom: 1px solid #e0e0e0;
    border-left: 3px solid #4a90d9;
    margin: 0;
}

.root-author {
    font-weight: 700;
    font-size: 0.9rem;
    margin-bottom: 2px;
}

.root-content {
    font-size: 0.85rem;
    color: #555;
    line-height: 1.4;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.thread-reply {
    padding: 8px 16px;
}

.reply-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.reply-header .author {
    font-weight: 700;
    font-size: 0.85rem;
}

.reply-header .timestamp {
    font-size: 0.7rem;
    color: #999;
}

.reply-content {
    font-size: 0.85rem;
    color: #333;
    line-height: 1.4;
}

