arguments.file_text:
@page "/chat"
@using sv_733aab2a433f4385a0651f2f6b1bab3c.Components.Chat
@using sv_733aab2a433f4385a0651f2f6b1bab3c.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="sidebar-panel">
        <ChannelSidebar Channels="channels"
                        SelectedChannelId="selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="main-panel @(activeThreadRootId.HasValue ? "" : "expanded")">
        @if (selectedChannel is not null)
        {
            <div class="main-header">
                <h2># @selectedChannel.Name</h2>
                <span class="header-desc">@selectedChannel.Description</span>
            </div>

            <div class="message-list" @onscroll="HandleScroll" @ref="messageListRef">
                @if (isLoadingMore)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @foreach (var msg in messages)
                {
                    <MessageBubble Message="msg"
                                   ReplyCount="GetReplyCount(msg.Id)"
                                   OnOpenThread="OpenThread"
                                   OnReact="HandleReaction" />
                }
            </div>

            <MessageInput Placeholder="Message #@selectedChannel.Name"
                          OnSend="SendMessage" />
        }
        else
        {
            <div class="no-channel">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (activeThreadRootId.HasValue)
    {
        <div class="thread-panel-container">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnSendReply="SendThreadReply"
                         OnClose="CloseThread" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<Message> threadReplies = [];
    private Dictionary<int, int> replyCounts = new();
    private Channel? selectedChannel;
    private int selectedChannelId;
    private int? activeThreadRootId;
    private Message? threadRootMessage;
    private bool isLoadingMore;
    private bool allMessagesLoaded;
    private const int PageSize = 30;
    private ElementReference messageListRef;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = [];
        replyCounts.Clear();
        allMessagesLoaded = false;
        activeThreadRootId = null;
        threadRootMessage = null;
        threadReplies = [];

        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channelId);
        await BuildReplyCounts();
    }

    private async Task BuildReplyCounts()
    {
        replyCounts.Clear();
        // Count replies: messages with a ReplyToId reference a root message
        foreach (var msg in messages.Where(m => m.ReplyToId.HasValue))
        {
            var rootId = msg.ReplyToId!.Value;
            replyCounts.TryGetValue(rootId, out var count);
            replyCounts[rootId] = count + 1;
        }

        // Also load thread info for messages that are thread starters
        // (replies might not all be in the current page)
        foreach (var msg in messages.Where(m => !m.ReplyToId.HasValue))
        {
            if (!replyCounts.ContainsKey(msg.Id))
            {
                // Check if there are any replies by looking at messages referencing this one
                var count = messages.Count(m => m.ReplyToId == msg.Id);
                if (count > 0)
                    replyCounts[msg.Id] = count;
            }
        }
    }

    private int GetReplyCount(int messageId) =>
        replyCounts.TryGetValue(messageId, out var count) ? count : 0;

    private async Task HandleScroll()
    {
        // Pagination is triggered by JS interop in production;
        // here we provide the handler for scroll-to-top loading
        if (isLoadingMore || allMessagesLoaded) return;

        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(selectedChannelId, messages.Count, PageSize);
        if (older.Count < PageSize)
            allMessagesLoaded = true;

        messages.InsertRange(0, older);
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(int rootMessageId)
    {
        activeThreadRootId = rootMessageId;
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
        var threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        // Exclude the root message itself from replies
        threadReplies = threadMessages.Where(m => m.Id != rootMessageId).ToList();
    }

    private async Task SendThreadReply(string content)
    {
        if (activeThreadRootId is null || selectedChannel is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, activeThreadRootId);
        threadReplies.Add(reply);
        messages.Add(reply);

        // Update reply count
        replyCounts.TryGetValue(activeThreadRootId.Value, out var count);
        replyCounts[activeThreadRootId.Value] = count + 1;
    }

    private void CloseThread()
    {
        activeThreadRootId = null;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Update the local message's reactions
        var msg = messages.FirstOrDefault(m => m.Id == args.MessageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
        }
    }
}

